mapper.select:
SELECT n.id AS id, n.user_id AS userId, n.from_user_id AS fromUserId, u.username AS fromUsername, u.avatar AS fromUserAvatar, n.type AS type, n.content AS content, n.target_id AS targetId, n.target_type AS targetType, n.is_read AS isRead, n.create_time AS createTime FROM notification n LEFT JOIN user u ON n.from_user_id = u.id AND u.deleted = 0 WHERE n.deleted = 0 AND n.user_id = #{userId}
AND n.type = #{type}
AND n.is_read = #{isRead}
ORDER BY n.create_time DESC
